# Run from the package root after 44:  Rscript data-raw/qa/44b_survey_pairing_text.R
# Writes, from the numbers of 44_survey_pairing_numbers.R and the survey layer, the text on how survey lines were paired with SPC tornadoes:
#   data-raw/survey/pairing_help.md, settings_help.md, status_definitions.md   read by R/survey.R and R/data_survey.R
#   data-raw/survey/pairing_issues.md, settings_issues.md                      with the tables; put into known_issues.md by 46_survey_path_accuracy.R
suppressMessages({library(sf); library(dplyr)}); options(width = 220)
source("data-raw/qa/helpers.R")
for (f in c("tornado_tracks", "survey_matches", "tornado_exposure")) load(file.path("data", paste0(f, ".rda")))
sm <- survey_matches; out <- readRDS(qa_out("survey_layer_numbers.rds")); Tt <- tornado_tracks[as.integer(substr(tornado_tracks$tornado_id, 1, 4)) >= 2007, ]
f0 <- function(x) format(x, big.mark = ",", trim = TRUE); pc <- function(x, d = 1) sprintf(paste0("%.", d, "f%%"), 100 * x)
md_table <- function(d) paste(c(paste0("| ", paste(names(d), collapse = " | "), " |"), paste0("|", paste(rep("---", ncol(d)), collapse = "|"), "|"), apply(d, 1, function(r) paste0("| ", paste(r, collapse = " | "), " |"))), collapse = "\n")
F <- list(lines = data.frame(x = seq_len(out$counts$lines_fetched))); Du <- data.frame(x = seq_len(out$counts$lines_distinct)); P <- data.frame(x = seq_len(out$counts$polygons))
n_lines <- out$counts$lines_distinct; n_pairs <- out$counts$pairs; st <- out$counts$status
# ---- text ----------------------------------------------------------------------------------------------------------------------------------------------------------------
w <- out$window; wt <- md_table(data.frame(`Date window (days)` = w$days, `Candidate pairs` = f0(w$candidate_pairs), `Tornadoes paired` = f0(w$paired), `Tornadoes with a usable swath` = f0(w$usable), check.names = FALSE))
p_need <- paste0("**Why a rule is needed.** The survey database and SPC's database share no identifier, so each SPC tornado is paired with a survey line by comparing dates and paths. Survey lines that are exact copies of each other (same date, length and coordinates) are merged first: ", f0(out$counts$lines_fetched), " lines became ", f0(n_lines), ". Survey lines dated after ", max(tornado_exposure$year), ", the last year of the SPC data, are ignored.")
dw <- readRDS(qa_out("date_window_check.rds")); dtab <- dw$tab; dcmp <- dw$cmp; ndiff <- dw$by_diff; dtt <- dw$dt_tab; n1 <- as.integer(ndiff[["1"]]); nall <- dw$n_pairs
n_utc <- dcmp$pairs[2] + dcmp$pairs[3]
date_tab <- md_table(data.frame(Pairs = c("same date", "date differs by 1 day"), Count = f0(dtab$pairs[1:2]), `Median distance (km)` = sprintf("%.3f", dtab$median_dist_km[1:2]), `90th percentile of the distance (km)` = sprintf("%.3f", dtab$p90_dist_km[1:2]), `Median length ratio` = sprintf("%.2f", dtab$median_length_ratio[1:2]),
  `Same state` = sprintf("%.1f%%", dtab$same_state[1:2]), `With a usable swath` = sprintf("%.1f%%", dtab$usable[1:2]), check.names = FALSE))
p_date <- paste0("**Date window.** The candidates for a tornado are the survey lines dated within 1 day of it. The value of 1 day does not come from an external source. It was tested at 0, 1 and 2 days (table below): ", f0(w$paired[1]), " tornadoes are paired and ", f0(w$usable[1]), " have a usable swath with 0 days, ", f0(w$paired[2]), " and ", f0(w$usable[2]), " with 1 day, and ", f0(w$paired[3]), " and ", f0(w$usable[3]), " with 2 days. One day was used because 0 days leaves ", f0(w$paired[2] - w$paired[1]), " fewer tornadoes paired and 2 days adds only ", f0(w$paired[3] - w$paired[2]), " (and ", abs(w$usable[3] - w$usable[2]), " more usable swath", ifelse(abs(w$usable[3] - w$usable[2]) == 1, "", "s"), "). ",
  "Dates differ by a day because of the time zone. The service stores the storm date as a date and time in UTC, and SPC records times in CST, six hours behind UTC (SPC database description, field 7, `tz`: \"All times, except for ?=unknown and 9=GMT, were converted to 3=CST\"). For ", f0(n_utc), " of the ", f0(nall), " pairs (", pc(n_utc / nall), ") the survey date equals the UTC date of SPC's time, and ", f0(n1), " pairs (", pc(n1 / nall), ") have a survey date one day later than SPC's; of those, ", f0(dw$late[1]), " (", pc(dw$late[1] / dw$late[2]), ") have an SPC time of 18:00 CST (00:00 UTC) or later. The survey time of day equals SPC's time converted to UTC for ", sprintf("%.1f%%", dtt$same_hour_of_day_as_survey), " of the pairs (within one hour for ", sprintf("%.1f%%", dtt$within_1h), "). Pairs one day apart are as close as pairs on the same date (table below), and only ", f0(as.integer(ndiff[["-1"]])), " pairs have a survey date one day earlier.")
p_dist <- "**Distance.** The distance between a tornado and a survey line is measured in kilometers. Take 21 equally spaced points along each path, from its start to its end; the distance is the mean of the 21 distances between the points with the same number, with the survey line read in whichever direction (start to end, or end to start) gives the smaller mean. For an SPC point track, which has no direction, the distance is the distance from the point to the survey line."
p_rule <- "**Pairing rule.** An SPC tornado is paired with its closest survey line when that line's closest tornado is also that tornado. Nothing else decides the pairing: there is no limit on the distance, no test on length or direction, no minimum length of survey line, and no tornado is left out as ambiguous. The reason is that this is the rule with the fewest steps: no value chosen by us (a distance limit, a length test) is imposed on the data."
p_count <- paste0("**Counts.** Of the ", f0(n_lines), " survey lines, ", f0(n_pairs), " are paired (", pc(n_pairs / n_lines), "); of the ", f0(nrow(Tt)), " SPC tornadoes since 2007, ", f0(n_pairs), " are paired (", pc(n_pairs / nrow(Tt)), ").")
pair_txt <- paste(p_need, p_date, p_dist, p_rule, p_count, sep = "\n\n")
pair_issues <- paste(p_need, p_date, wt, date_tab, p_dist, p_rule, p_count, sep = "\n\n")
limit_txt <- paste0("**Limitation.** The rule has no cut-off, so a tornado with no real survey counterpart can be paired with a distant survey line: ", f0(out$counts$far), " of the ", f0(n_pairs), " pairs (", pc(out$counts$far / n_pairs), ") have a survey line farther away than the larger of the SPC tornado's reported length and 0.1 mile (the shortest length assumed in SPC's older format description), ", f0(out$counts$far_usable), " of them with a usable swath; the distance and length ratio of every pair are in `survey_matches`.")
sf_ <- out$swath_filter
swath_txt <- paste0("**Swath filter.** The survey database has damage polygons, not one swath per tornado. For a paired tornado, the polygons that cross the surveyed centerline on the same date (within one day) are kept when they are rated EF0 to EF5 and at least 90% of their area lies within a distance from the centerline equal to the SPC path width plus 500 m (this removes polygons of neighboring tornadoes and straight-line wind). The kept polygons are merged into the swath, which is usable when it lies within 200 m of at least 50% of the centerline's length. None of the four values (90%, 500 m, 200 m, 50%) comes from an external source. Each was changed in turn (table below). The number of tornadoes with a usable swath is ",
  f0(sf_$usable[1]), " with the values used and ranges from ", f0(min(sf_$usable)), " to ", f0(max(sf_$usable)), " across the alternatives; the largest loss is ", max(sf_$lost), " tornadoes (", sf_$setting[which.max(sf_$lost)], ") and the largest gain ", max(sf_$gained), " (", sf_$setting[which.max(sf_$gained)], "). ", if (all(sf_$p90_abs_area_change_pct == 0)) "For tornadoes with a usable swath under both settings the swath area does not change." else paste0("For tornadoes with a usable swath under both settings, the median change in swath area is between ", sprintf("%.2f", min(sf_$median_area_change_pct)), "% and ", sprintf("%.2f", max(sf_$median_area_change_pct)), "% and the 90th percentile of the absolute change is at most ", sprintf("%.2f", max(sf_$p90_abs_area_change_pct)), "%."))
rs <- out$resolution
res_txt <- paste0("**Polygon resolution.** The damage polygons were fetched with the service's generalization set to 0.0002 degrees (about 20 m), and the polygons stored in `survey_tracks` for plotting and distances are simplified to 50 m (no outline point moves by more than 50 m). Against full-resolution polygons, the area of the 20 m swaths has a median change of ", sprintf("%.2f", rs$median_change_pct[1]), "% and a 90th percentile of the absolute change of ", sprintf("%.2f", rs$p90_abs_change_pct[1]), "% (largest ", sprintf("%.1f", rs$max_abs_change_pct[1]), "%); ", ifelse(out$resolution_usable_in_one_only == 0, "no tornado changes", paste(out$resolution_usable_in_one_only, "tornadoes change")), " usability. The 50 m polygons differ from the 20 m swaths by a median of ", sprintf("%.2f", rs$median_change_pct[2]), "% and a 90th percentile of ", sprintf("%.2f", rs$p90_abs_change_pct[2]), "% (largest ", sprintf("%.1f", rs$max_abs_change_pct[2]), "%), which matters for small swaths. The exposure columns of `survey_exposure` come from the 20 m swaths, so only plots and `centroid_dist_km` use the simplified polygons.")
sum_nr <- sum(sm$n_polygons_raw[sm$status != "no_pair"]); sum_nu <- sum(sm$n_polygons_used[sm$status != "no_pair"]); with_poly <- sum(sm$n_polygons_used > 0, na.rm = TRUE)
no_poly <- sum(sm$status == "no_swath" & sm$n_polygons_used == 0); low_cov <- sum(sm$status == "no_swath" & sm$n_polygons_used > 0)
defs <- data.frame(Status = c("included", "no_swath", "no_pair"), Meaning = c(
  "The tornado was paired with a survey line (its closest survey line, whose closest tornado is also this tornado) and the survey has a usable damage swath (below). It is in `survey_exposure` and `survey_tracks`.",
  "The tornado was paired with a survey line, but no rated damage polygon remains along the surveyed centerline after the swath filter, or the remaining polygons lie within 200 meters of under 50% of the centerline. No exposure is computed.",
  "No survey line is paired with the tornado: its closest survey line has another tornado that is closer to it, or no survey line is dated within 1 day of the tornado."),
  Count = c(f0(st[["included"]]), paste0(f0(st[["no_swath"]]), " (", f0(no_poly), " with no polygon left, ", f0(low_cov), " with polygons near under half of the centerline)"), paste0(f0(st[["no_pair"]]), " (", f0(out$counts$no_candidate), " with no survey line dated within 1 day)")), check.names = FALSE)
defs2 <- data.frame(Term = c("Usable damage swath", "Swath filter"), Rule = c("The swath (the kept damage polygons, merged) lies within 200 meters of at least 50% of the length of the surveyed centerline (`swath_cover` of 0.5 or more).",
  "Of the damage polygons that cross the surveyed centerline on the same date (within one day), keep those rated EF0 to EF5 whose area lies at least 90% within a distance from the centerline equal to the SPC path width plus 500 meters."),
  Count = c(paste0(f0(st[["included"]]), " of the ", f0(st[["included"]] + st[["no_swath"]]), " paired tornadoes"), paste0("Of the ", f0(sum_nr), " polygons crossing the centerlines of the paired tornadoes, ", f0(sum_nu), " were kept; ", f0(with_poly), " tornadoes keep at least one")), check.names = FALSE)
help_sub <- function(x) gsub("(table below)", "(table in `data-raw/known_issues.md`)", x, fixed = TRUE)
writeLines(help_sub(paste(c(pair_txt, "", limit_txt), collapse = "\n")), "data-raw/survey/pairing_help.md")
writeLines(paste(c(pair_issues, "", limit_txt), collapse = "\n"), "data-raw/survey/pairing_issues.md")
writeLines(help_sub(paste(c(swath_txt, "", res_txt), collapse = "\n")), "data-raw/survey/settings_help.md")
writeLines(paste(c(swath_txt, "", md_table(data.frame(Setting = sf_$setting, `Tornadoes with a usable swath` = f0(sf_$usable), Gained = f0(sf_$gained), Lost = f0(sf_$lost), `Median change in swath area (%)` = sprintf("%.2f", sf_$median_area_change_pct), `90th percentile of the absolute change (%)` = sprintf("%.2f", sf_$p90_abs_area_change_pct), check.names = FALSE)), "", res_txt, "",
  md_table(data.frame(Comparison = rs$comparison, Tornadoes = f0(rs$tornadoes), `Median change in area (%)` = sprintf("%.2f", rs$median_change_pct), `90th percentile of the absolute change (%)` = sprintf("%.2f", rs$p90_abs_change_pct), `Largest absolute change (%)` = sprintf("%.1f", rs$max_abs_change_pct), check.names = FALSE))), collapse = "\n"), "data-raw/survey/settings_issues.md")
writeLines(paste(c("**Values of `status` in `survey_matches`.**", "", md_table(defs), "", "**Terms.**", "", md_table(defs2)), collapse = "\n"), "data-raw/survey/status_definitions.md")
cat("wrote data-raw/survey/*.md\n")
